class Solution:
    def waysToReachTarget(self, target: int, types: list[list[int]]) -> int:
        MOD = 1000000007
        def dfs(i: int, score: int) -> int:
            if score > target:
                return 0
            if i == len(types):
                return 1 if score == target else 0
            cnt, marks = types[i]
            ans = 0
            for take in range(cnt + 1):
                ans += dfs(i + 1, score + take * marks)
            return ans % MOD
        return dfs(0, 0)

